<?php
namespace App\Models;use Illuminate\Database\Eloquent\Model;class BookingPassenger extends Model{use \App\Models\Concerns\RecordsActivity;public function activityLabel():string{return trim("{$this->first_name} {$this->last_name}").' · '.(Booking::whereKey($this->booking_id)->value('reference')??'booking');}protected $fillable=['booking_id','pickup_point_id','first_name','last_name','category','price_code','price','room_number','seat_number','age','date_of_birth','phone','email','meal_selection','notes'];protected $casts=['date_of_birth'=>'date','price'=>'decimal:2'];public function booking(){return $this->belongsTo(Booking::class);}public function pickupPoint(){return $this->belongsTo(PickupPoint::class);}}
